'use strict';
let feltNeed='',reflectionFits=false;
const careNeeds=[['clarity','Clarity','Thodi samajh'],['reassurance','Reassurance','Thoda bharosa'],['connection','Connection','Kisi ka saath'],['rest','Rest','Aaram'],['space','Space','Thodi jagah'],['respect','Respect','Meri baat ki kadar'],['agency','A little choice','Apni marzi ka ek kadam'],['acceptance','Acceptance','Bina judge hue rehna']];
const feelingNeeds={overwhelmed:['space','rest','clarity'],anxious:['reassurance','clarity','connection'],looping:['clarity','space','reassurance'],sad:['connection','rest','acceptance'],lonely:['connection','acceptance','reassurance'],ashamed:['acceptance','reassurance','respect'],guilty:['clarity','acceptance','agency'],angry:['respect','space','agency'],numb:['rest','connection','space'],exhausted:['rest','space','connection'],uncertain:['clarity','agency','reassurance'],jealous:['acceptance','clarity','respect'],restless:['space','agency','rest'],hurt:['respect','connection','space'],okay:['clarity','connection','agency'],unsure:['space','clarity','connection']};
const feelingPossibilities={overwhelmed:'Kya bahut si demands ek saath aa rahi hain, aur unke beech apni jagah kam pad rahi hai?',anxious:'Kya abhi uncertainty, galti ka darr, ya thode bharose ki zaroorat ke aas-paas baat hai?',looping:'Kya mann kisi baat ko samajhna chahta hai, par har round mein nayi jaankari nahi mil rahi?',sad:'Kya koi kami, disappointment, ya bas ek heavy sa din hai? Wajah clear hona zaroori nahi.',lonely:'Kya logon ki ginti se zyada, samjhe jaane aur apnapan ki kami chubh rahi hai?',ashamed:'Kya kisi ghatna ya comparison se apne poore aap par sakht faisla aa raha hai?',guilty:'Kya koi specific baat sudharni hai, ya apne hisse se zyada zimmedari mehsoos ho rahi hai?',angry:'Kya koi boundary, unmet need, ya baar-baar ka pressure dhyaan maang raha hai?',numb:'Kya words ya feelings door lag rahe hain? Abhi unhe force karne ki zaroorat nahi.',exhausted:'Kya abhi samajhne se pehle thoda bojh kam karna ya aaram ki jagah banana zaroori lagta hai?',uncertain:'Kya koi decision itna bada lag raha hai ki chhota agla kadam bhi dhundhla ho gaya hai?',jealous:'Kya comparison kisi apni khwahish, darr, ya recognition ki zaroorat ko chhoo raha hai?',restless:'Kya kisi intezaar, pressure, ya energy ko jagah chahiye? Iska ek hi matlab hona zaroori nahi.',hurt:'Kya respect, care, honesty, ya belonging mein se kuch missing laga?',okay:'Kya is relatively theek pal mein apne baare mein kuch jaanne ki curiosity hai?',unsure:'Naam abhi nahi mil raha toh bhi theek hai. Hum bas ek possible need se shuru kar sakte hain.'};
function careChoices(){const ids=feelingNeeds[currentMood().id]||feelingNeeds.unsure;return `<div class="field">Is waqt kis cheez ki zaroorat lagti hai?</div><div class="chips">${ids.map(id=>{const n=careNeeds.find(x=>x[0]===id);return `<button class="chip ${feltNeed===id?'selected':''}" data-care-need="${id}" aria-pressed="${feltNeed===id}">${n[1]}${hi(n[2])}</button>`}).join('')}<button class="chip ${feltNeed==='unsure'?'selected':''}" data-care-need="unsure" aria-pressed="${feltNeed==='unsure'}">Abhi pata nahi</button></div><p class="small">Jo fit ho, wahi. Skip karna bhi okay hai.</p>`}
function quickRefine(){if(!selected.length)selected=['unsure'];const m=currentMood();return `${button('‹ Feeling words','go-mood','back')}<p class="greeting">Do chhote choices. Phir ek reflection.</p><h1>Thoda aur samjhein?</h1><p class="sub">${selected.map(id=>esc(moodData.find(m=>m.id===id).name)).join(' + ')}${hi(m.hi)}</p><div class="field">Inmein se kya kareeb lagta hai?</div><div class="chips">${m.nuances.map(([en,h])=>`<button class="chip ${nuance===en?'selected':''}" data-nuance="${esc(en)}" aria-pressed="${nuance===en}">${en}${hi(h)}</button>`).join('')}</div>${careChoices()}<details><summary>Intensity ya apne words add karna chaaho?</summary><label class="field" for="custom-feeling">Apne words <span class="small">(optional)</span></label><input id="custom-feeling" type="text" maxlength="140" value="${esc(context)}" placeholder="Jo choices mein nahi aaya…"><label class="field" for="intensity">Kitna heavy lag raha hai? <span id="intensity-value">${intensity}/5</span></label><input id="intensity" type="range" min="1" max="5" value="${intensity}"></details>${button('Mujhe reflection dikhao','support')}${button('Details skip karke reflection','skip-refinement','text-btn')}`}
function understandingReflection(){const m=currentMood(),need=careNeeds.find(x=>x[0]===feltNeed);return `<section class="understanding-panel"><p class="small">Ek possibility, final answer nahi.</p><h2>Chalo, isko thoda samjhein.</h2><p>Tumne ${selected.length?selected.map(id=>esc(moodData.find(m=>m.id===id).name.toLowerCase())).join(' aur '):'abhi feeling ka naam clear nahi'} choose kiya${nuance?', aur “'+esc(nuance)+'” kareeb laga':''}.</p><p>${esc(feelingPossibilities[m.id])}</p>${need?`<p>Tumne <strong>${esc(need[2].toLowerCase())}</strong> ko apni need bataya. Isko abhi solve karne ki jagah, pehle iske liye thodi jagah bana sakte hain.</p>`:'<p>Need abhi clear nahi hai toh bhi yeh reflection adhoori nahi. Tum ise change kar sakte ho.</p>'}${context?`<p class="small">Tumhare apne words: “${esc(context)}”</p>`:''}<div class="passage-actions"><button class="text-btn" data-action="reflection-fits">Kuch toh fit hota hai</button><button class="text-btn" data-action="revise-reflection">Yeh fit nahi hua</button></div>${reflectionFits?'<p class="small" role="status">Theek. Jo hissa fit hua, bas utna rakho. Baaki chhod sakte ho.</p>':''}<p class="small">We’re reflecting your choices, not inferring a diagnosis or the cause of your feeling.</p></section>`}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.careNeed){feltNeed=feltNeed===el.dataset.careNeed?'':el.dataset.careNeed;reflectionFits=false;render(true);return}if(el.dataset.action==='reflection-fits'){reflectionFits=true;render(true)}if(el.dataset.action==='revise-reflection'){reflectionFits=false;go('refine')}if(el.dataset.action==='skip-refinement'){nuance='';feltNeed='';go('support')}if(el.dataset.action==='unnamed-feeling'){selected=['unsure'];nuance='';feltNeed='';go('refine')}});
